            state_map = {
                "new": "1",
                "in_progress": "2",
                "on_hold": "3",
                "resolved": "6",
                "closed": "7",
                "canceled": "8",
                "cancelled": "8"
            }
            if state_val.lower() in state_map:
                args["state"] = state_map[state_val.lower()]

