        "app_name", "appName", "site_name", "siteName", "webapp_name", "web_app",
        "project", "projectName", "projectId", "project_id",
        "repo", "repository", "repositoryId", "repository_id", "repo_name",
        "owner", "user", "username", "org", "organization",
