@mcp.tool()
def create_project(path_or_params: Optional[Dict[str, Any]] = None, **kwargs) -> str:
    """Create a new Azure DevOps project in the organization with Git version control and process template"""
    creds = get_credentials()
    base = creds["base_url"]
    headers, auth = get_headers_and_auth(creds)
    srv_lower = "azure_devops".lower()
    
    args = dict(kwargs)
    if isinstance(path_or_params, dict):
        args.update(path_or_params)
        
    target_endpoint = "/_apis/projects"
    if " or " in target_endpoint:
        target_endpoint = target_endpoint.split(" or ")[0].strip()
    if " OR " in target_endpoint:
        target_endpoint = target_endpoint.split(" OR ")[0].strip()
    if "," in target_endpoint:
        target_endpoint = target_endpoint.split(",")[0].strip()

    # Smart ServiceNow handling (INC number resolution & state translation)
    if any(w in srv_lower for w in ["servicenow", "service_now", "snow"]):
        state_val = args.get("state")
        if isinstance(state_val, str) and not state_val.isdigit():
            state_map = {
                "new": "1",
                "in_progress": "2",
                "on_hold": "3",
                "resolved": "6",
                "closed": "7",
                "canceled": "8",
                "cancelled": "8"
            }
            if state_val.lower() in state_map:
                args["state"] = state_map[state_val.lower()]

        # Map generic 'query' or 'filter' to ServiceNow 'sysparm_query'
        if "query" in args and "sysparm_query" not in args:
            args["sysparm_query"] = args.pop("query")
        if "filter" in args and "sysparm_query" not in args:
            args["sysparm_query"] = args.pop("filter")
        if "limit" in args and "sysparm_limit" not in args:
            args["sysparm_limit"] = args.pop("limit")
        if "top" in args and "sysparm_limit" not in args:
            args["sysparm_limit"] = args.pop("top")

        # Map resolution and closing fields to prevent Data Policy Exceptions
        if "create_project" == "resolve_incident" or str(args.get("state")) == "6":
            args["state"] = "6"
            args["incident_state"] = "6"
            if "resolution_code" in args and "close_code" not in args:
                args["close_code"] = args.pop("resolution_code")
            if "resolution_notes" in args and "close_notes" not in args:
                args["close_notes"] = args.pop("resolution_notes")
            code_lower = str(args.get("close_code", "")).lower()
            if "workaround" in code_lower:
                args["close_code"] = "Workaround provided"
            else:
                args["close_code"] = "Solution provided"
            if not args.get("close_notes"):
                args["close_notes"] = args.get("work_notes") or args.get("notes") or "Resolved by Autonomous SRE AI."

        if "create_project" == "close_incident" or str(args.get("state")) == "7":
            args["state"] = "7"
            args["incident_state"] = "7"
            if not args.get("close_code"):
                args["close_code"] = "Solution provided"
            if not args.get("close_notes"):
                args["close_notes"] = args.get("work_notes") or args.get("notes") or "Closed by Autonomous SRE AI."

        if "work_note" in args and "work_notes" not in args:
            args["work_notes"] = args.pop("work_note")

        # Map incident identifiers
        inc_val = args.get("incident_id") or args.get("number") or args.get("sys_id") or args.get("id")
        if inc_val:
            args["sys_id"] = str(inc_val).strip()
            args["incident_id"] = str(inc_val).strip()

    # Domain specific parameter extractions
    vm_val = args.get("vm_name") or args.get("virtual_machine_name") or args.get("vmName") or args.get("target_vm") or args.get("name") or ""
    app_val = args.get("app_service_name") or args.get("app_name") or args.get("appName") or args.get("site_name") or args.get("siteName") or args.get("webapp_name") or args.get("web_app") or args.get("name") or creds.get("app_service_name") or ""
    if not app_val or any(d in str(app_val).lower() for d in ["your-", "default", "<app", "app_service", "undefined", "null"]):
        app_val = creds.get("app_service_name") or os.environ.get("AZURE_APP_SERVICE_NAME", "devops-vsp-sample-app-shakil")

    item_id_val = args.get("incident_id") or args.get("number") or args.get("sys_id") or args.get("id") or args.get("item_id") or args.get("record_id") or ""

    sub_val = args.get("subscription_id") or args.get("subscriptionId") or args.get("subscription") or args.get("sub_id")
    if not sub_val or any(d in str(sub_val).lower() for d in ["12345678", "your-", "default", "<sub", "subscription", "undefined", "null"]):
        sub_val = creds.get("subscription_id") or creds.get("azure_subscription_id") or os.environ.get("AZURE_SUBSCRIPTION_ID", "60e3a39b-c3bc-4a0e-935e-f3ef0daceb93")

    rg_val = args.get("resource_group") or args.get("resourceGroupName") or args.get("resource_group_name") or args.get("rg")
    if not rg_val or any(d in str(rg_val).lower() for d in ["your-", "default", "<rg", "resource_group", "undefined", "null"]):
        rg_val = creds.get("resource_group") or creds.get("azure_resource_group") or os.environ.get("AZURE_RESOURCE_GROUP", "rg-devops-uaenorth")

